insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('c03ad783-0bdb-54d5-a59c-8516bff95f85','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Ayo menghitung buah','matematika-kelas-1',1,'A','Bab 1','dasar','draft',5,'{"summary":"Menghitung benda sampai 10 dan mencoba penjumlahan sederhana.","video_url":null,"blocks":[{"type":"text","body":"Nara membawa 3 apel. Kakak memberinya 2 apel lagi. Yuk, hitung satu per satu: 1, 2, 3, 4, 5. Sekarang Nara memiliki 5 apel."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Gunakan jari atau benda kecil. Tambah berarti jumlahnya bertambah."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('ba6fdf70-52f9-5e1f-9451-de3e31779fd7','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Kucing di teras','bahasa-indonesia-kelas-1',1,'A','Bab 1','dasar','draft',5,'{"summary":"Membaca dengan teliti dan menemukan informasi dalam cerita.","video_url":null,"blocks":[{"type":"text","body":"Mimi adalah kucing Nara. Bulunya putih. Setiap pagi, Mimi duduk di teras. Nara memberi Mimi air bersih."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Cari kata tanya: siapa, apa, di mana, dan kapan. Jawab berdasarkan cerita."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('69be5379-98bb-56b7-af8b-aa866e5867bc','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Merawat tubuh dan lingkungan','ipas-kelas-1',1,'A','Bab 1','dasar','draft',5,'{"summary":"Mengenali kebiasaan sehat dan lingkungan bersih.","video_url":null,"blocks":[{"type":"text","body":"Nara mencuci tangan dengan sabun sebelum makan. Ia minum air bersih, makan beragam makanan, dan cukup beristirahat. Sampah dibuang pada tempatnya agar lingkungan nyaman."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Amati lingkungan tanpa merusak tumbuhan atau mengganggu hewan. Mintalah pendampingan orang dewasa."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('a82e5045-f5f1-53c2-88ee-486421081cff','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Teman berbeda, tetap bersama','pancasila-kelas-1',1,'A','Bab 1','dasar','draft',5,'{"summary":"Berlatih menghargai perbedaan, mendengar, dan bertanggung jawab.","video_url":null,"blocks":[{"type":"text","body":"Kelas Nara ingin merawat taman. Setiap anak boleh menyampaikan pendapat. Mereka mendengarkan tanpa mengejek, lalu bermusyawarah. Tugas dibagi dengan adil. Saat ada teman kesulitan, teman lain membantu. Semua menjaga keputusan bersama."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Berbeda pendapat itu wajar. Dengarkan alasan teman dan bicaralah dengan sopan."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('e82a5e37-3b19-5ec0-8aca-e148b6c830ee','620ca8d1-025d-5ecc-80e1-727f5c59216d','Hello, new friends!','bahasa-inggris-kelas-1',1,'A','Bab 1','dasar','draft',5,'{"summary":"Mengenal kosakata bahasa Inggris melalui kalimat sederhana.","video_url":null,"blocks":[{"type":"text","body":"Hello! My name is Nara. I have a little garden. The leaves are green. There are three flowers. I water the plants every morning. Thank you for helping me!"},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Baca perlahan. Cocokkan kata dengan benda atau kegiatan di sekitarmu."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('68199e04-a9bb-57c1-ae77-882753ef1d3e','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Warna-warni di sekitarku','seni-budaya-kelas-1',1,'A','Bab 1','dasar','draft',5,'{"summary":"Mengenal warna dan kolase sambil berani mengekspresikan ide.","video_url":null,"blocks":[{"type":"text","body":"Nara membuat kolase taman dari potongan kertas. Ia menggabungkan merah dan kuning untuk mendapatkan jingga pada cat. Bentuk disusun sebelum direkatkan. Nara menggunakan bahan dengan hemat dan merapikan meja setelah berkarya. Setiap karya boleh berbeda."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Gunakan gunting dengan pendampingan orang dewasa. Hargai karyamu dan karya teman."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('010aa341-80c8-5844-94d4-6218c0cd4211','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Penjumlahan dua bilangan','matematika-kelas-2',2,'A','Bab 1','dasar','draft',5,'{"summary":"Mengenal puluhan dan satuan melalui penjumlahan.","video_url":null,"blocks":[{"type":"text","body":"Di perpustakaan ada 24 buku cerita. Datang 13 buku baru. Jumlahkan satuan: 4 + 3 = 7. Lalu puluhan: 20 + 10 = 30. Jadi, ada 37 buku."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Pisahkan puluhan dan satuan agar lebih mudah menghitung."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('a156f01d-85b5-5585-909a-eeb5ad1a8580','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Bekal untuk sahabat','bahasa-indonesia-kelas-2',2,'A','Bab 1','dasar','draft',5,'{"summary":"Membaca dengan teliti dan menemukan informasi dalam cerita.","video_url":null,"blocks":[{"type":"text","body":"Bima membawa roti ke sekolah. Saat istirahat, Bima melihat Dita lupa membawa bekal. Bima membagi rotinya. Mereka makan bersama di bangku taman."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Cari kata tanya: siapa, apa, di mana, dan kapan. Jawab berdasarkan cerita."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
