insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('ddf81f29-48f4-5147-9a05-cc18fcf88691','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Warna-warni di sekitarku','seni-budaya-kelas-2',2,'A','Bab 1','dasar','draft',5,'{"summary":"Mengenal warna dan kolase sambil berani mengekspresikan ide.","video_url":null,"blocks":[{"type":"text","body":"Nara membuat kolase taman dari potongan kertas. Ia menggabungkan merah dan kuning untuk mendapatkan jingga pada cat. Bentuk disusun sebelum direkatkan. Nara menggunakan bahan dengan hemat dan merapikan meja setelah berkarya. Setiap karya boleh berbeda."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Gunakan gunting dengan pendampingan orang dewasa. Hargai karyamu dan karya teman."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('552edba5-0b1a-5b93-9c61-f0233e490359','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Perkalian di kebun Nara','matematika-kelas-3',3,'B','Bab 1','dasar','draft',5,'{"summary":"Menemukan perkalian sebagai penjumlahan berulang.","video_url":null,"blocks":[{"type":"text","body":"Nara menanam 4 baris wortel. Setiap baris berisi 3 tanaman. Banyak tanaman adalah 3 + 3 + 3 + 3 = 12. Kita juga dapat menulis 4 × 3 = 12."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Gambarkan kelompok dengan jumlah anggota yang sama, lalu hitung semuanya."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('f7e3612b-6565-5941-9fb3-3822477f6f04','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Kebun kecil Nara','bahasa-indonesia-kelas-3',3,'B','Bab 1','dasar','draft',5,'{"summary":"Membaca dengan teliti dan menemukan informasi dalam cerita.","video_url":null,"blocks":[{"type":"text","body":"Nara menanam kacang hijau dalam pot. Setiap pagi ia menyiramnya secukupnya. Pot diletakkan dekat jendela agar mendapat cahaya. Setelah beberapa hari, tunas muncul. Nara mencatat pertumbuhannya di buku."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Cari kata tanya: siapa, apa, di mana, dan kapan. Jawab berdasarkan cerita."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('1ba38fd3-8875-5db4-8fac-3623e931022e','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Tumbuhan juga butuh perawatan','ipas-kelas-3',3,'B','Bab 1','dasar','draft',5,'{"summary":"Mengenali bagian tumbuhan dan kebutuhannya.","video_url":null,"blocks":[{"type":"text","body":"Akar menyerap air dari tanah. Batang menopang tumbuhan. Daun menggunakan cahaya untuk membantu membuat makanan. Tanaman di kebun Nara mendapat air secukupnya dan sinar matahari."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Amati lingkungan tanpa merusak tumbuhan atau mengganggu hewan. Mintalah pendampingan orang dewasa."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('3a5aa5a0-255f-53c6-a329-651d75b38545','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Musyawarah di kelas kita','pancasila-kelas-3',3,'B','Bab 1','dasar','draft',5,'{"summary":"Berlatih menghargai perbedaan, mendengar, dan bertanggung jawab.","video_url":null,"blocks":[{"type":"text","body":"Kelas Nara ingin merawat taman. Setiap anak boleh menyampaikan pendapat. Mereka mendengarkan tanpa mengejek, lalu bermusyawarah. Tugas dibagi dengan adil. Saat ada teman kesulitan, teman lain membantu. Semua menjaga keputusan bersama."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Berbeda pendapat itu wajar. Dengarkan alasan teman dan bicaralah dengan sopan."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('9f2d3084-03df-562a-9753-be77dfd5c61b','620ca8d1-025d-5ecc-80e1-727f5c59216d','A day in the garden','bahasa-inggris-kelas-3',3,'B','Bab 1','dasar','draft',5,'{"summary":"Mengenal kosakata bahasa Inggris melalui kalimat sederhana.","video_url":null,"blocks":[{"type":"text","body":"Hello! My name is Nara. I have a little garden. The leaves are green. There are three flowers. I water the plants every morning. Thank you for helping me!"},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Baca perlahan. Cocokkan kata dengan benda atau kegiatan di sekitarmu."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('667d259d-c4c5-5dc5-8a0d-dfda00f58a1b','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Membuat kolase kebun','seni-budaya-kelas-3',3,'B','Bab 1','dasar','draft',5,'{"summary":"Mengenal warna dan kolase sambil berani mengekspresikan ide.","video_url":null,"blocks":[{"type":"text","body":"Nara membuat kolase taman dari potongan kertas. Ia menggabungkan merah dan kuning untuk mendapatkan jingga pada cat. Bentuk disusun sebelum direkatkan. Nara menggunakan bahan dengan hemat dan merapikan meja setelah berkarya. Setiap karya boleh berbeda."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Gunakan gunting dengan pendampingan orang dewasa. Hargai karyamu dan karya teman."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('23bb76c6-78c7-51db-9934-1aba394dc814','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Membagi bekal dengan adil','matematika-kelas-4',4,'B','Bab 1','dasar','draft',5,'{"summary":"Memahami pembagian sebagai kelompok yang sama banyak.","video_url":null,"blocks":[{"type":"text","body":"Ada 24 potong buah untuk 6 teman. Setiap teman mendapat jumlah yang sama. Karena 6 × 4 = 24, setiap teman menerima 4 potong. Kita menulis 24 ÷ 6 = 4."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Gunakan perkalian untuk memeriksa hasil pembagian."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('868c3211-1e6b-5548-a6bc-5306b49b6ad1','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Perpustakaan keliling','bahasa-indonesia-kelas-4',4,'B','Bab 1','dasar','draft',5,'{"summary":"Membaca dengan teliti dan menemukan informasi dalam cerita.","video_url":null,"blocks":[{"type":"text","body":"Sinta membantu perpustakaan keliling setiap Sabtu. Ia menata buku cerita di rak mobil. Mobil berhenti di balai desa. Anak-anak bergantian meminjam buku. Sinta mencatat peminjaman agar buku dapat dikembalikan tepat waktu."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Cari kata tanya: siapa, apa, di mana, dan kapan. Jawab berdasarkan cerita."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('01c8156b-72ab-59e8-9554-17d33e2b9f9b','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Tumbuhan juga butuh perawatan','ipas-kelas-4',4,'B','Bab 1','dasar','draft',5,'{"summary":"Mengenali bagian tumbuhan dan kebutuhannya.","video_url":null,"blocks":[{"type":"text","body":"Akar menyerap air dari tanah. Batang menopang tumbuhan. Daun menggunakan cahaya untuk membantu membuat makanan. Tanaman di kebun Nara mendapat air secukupnya dan sinar matahari."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Amati lingkungan tanpa merusak tumbuhan atau mengganggu hewan. Mintalah pendampingan orang dewasa."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
