insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('db170b02-cdee-54a3-911b-e1a9844857ef','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Pecahan dalam kehidupan','matematika-kelas-5',5,'C','Bab 1','dasar','draft',5,'{"summary":"Menghitung bagian dari suatu kumpulan dengan pecahan sederhana.","video_url":null,"blocks":[{"type":"text","body":"Ada 20 biji kacang. Separuhnya akan ditanam hari ini. Separuh berarti satu dari dua bagian yang sama besar. Jadi, 20 ÷ 2 = 10 biji ditanam hari ini."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Untuk mencari 1/n bagian dari kumpulan, bagi jumlah benda dengan n."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('c72cecbd-fda3-5c48-8bc9-488d0ce2b54f','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Menjaga sungai bersama','bahasa-indonesia-kelas-5',5,'C','Bab 1','dasar','draft',5,'{"summary":"Membaca dengan teliti dan menemukan informasi dalam cerita.","video_url":null,"blocks":[{"type":"text","body":"Rafi mengajak teman-temannya membersihkan tepi sungai pada Minggu pagi. Mereka memilah sampah plastik dan daun. Sampah plastik dibawa ke tempat pengumpulan. Setelah selesai, Rafi menulis laporan agar kegiatan berikutnya dapat direncanakan lebih baik."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Cari kata tanya: siapa, apa, di mana, dan kapan. Jawab berdasarkan cerita."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('4b14855e-402f-5cd4-9d98-78001a366c31','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Rantai makanan di kebun','ipas-kelas-5',5,'C','Bab 1','dasar','draft',5,'{"summary":"Mengenali hubungan makhluk hidup dalam ekosistem.","video_url":null,"blocks":[{"type":"text","body":"Rumput menggunakan energi matahari untuk membuat makanan. Belalang memakan rumput. Katak memakan belalang. Hubungan ini membentuk rantai makanan: rumput → belalang → katak. Setiap makhluk hidup berperan dalam ekosistem."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Amati lingkungan tanpa merusak tumbuhan atau mengganggu hewan. Mintalah pendampingan orang dewasa."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
