insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('2b17ceca-8bdf-585f-a274-e8c314ff9f9e','620ca8d1-025d-5ecc-80e1-727f5c59216d','Describing our little garden','bahasa-inggris-kelas-5',5,'C','Bab 1','dasar','draft',5,'{"summary":"Mengenal kosakata bahasa Inggris melalui kalimat sederhana.","video_url":null,"blocks":[{"type":"text","body":"Hello! My name is Nara. I have a little garden. The leaves are green. There are three flowers. I water the plants every morning. Thank you for helping me!"},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Baca perlahan. Cocokkan kata dengan benda atau kegiatan di sekitarmu."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('12c35e6e-6eec-5098-9d36-ed44c9feb009','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Berkarya dari bahan sekitar','seni-budaya-kelas-5',5,'C','Bab 1','dasar','draft',5,'{"summary":"Mengenal warna dan kolase sambil berani mengekspresikan ide.","video_url":null,"blocks":[{"type":"text","body":"Nara membuat kolase taman dari potongan kertas. Ia menggabungkan merah dan kuning untuk mendapatkan jingga pada cat. Bentuk disusun sebelum direkatkan. Nara menggunakan bahan dengan hemat dan merapikan meja setelah berkarya. Setiap karya boleh berbeda."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Gunakan gunting dengan pendampingan orang dewasa. Hargai karyamu dan karya teman."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('0faabb8e-93ab-592b-bd0f-2fcdd4241535','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Persentase di kebun sekolah','matematika-kelas-6',6,'C','Bab 1','dasar','draft',5,'{"summary":"Menghubungkan persen dengan bagian dari seratus.","video_url":null,"blocks":[{"type":"text","body":"Sebanyak 25% dari 40 bibit adalah bibit tomat. Karena 25% = 25/100 = 1/4, banyak bibit tomat adalah 40 ÷ 4 = 10."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"50% = 1/2, 25% = 1/4, dan 10% = 1/10. Pecahan ini membantu menghitung cepat."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('985b2b8b-9468-5a0e-8c5b-542f186cb8e5','4f0111bf-ef26-57a9-8550-b3a891bb00a9','Penelitian taman sekolah','bahasa-indonesia-kelas-6',6,'C','Bab 1','dasar','draft',5,'{"summary":"Membaca dengan teliti dan menemukan informasi dalam cerita.","video_url":null,"blocks":[{"type":"text","body":"Alya mengamati kupu-kupu di taman sekolah setiap Jumat pagi. Ia mencatat jenis bunga yang dikunjungi. Pengamatan dilakukan dari jarak aman agar kupu-kupu tidak terganggu. Setelah empat minggu, Alya menyusun laporan berdasarkan catatannya, bukan dugaan semata."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Cari kata tanya: siapa, apa, di mana, dan kapan. Jawab berdasarkan cerita."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('8d7f0bf7-4326-5ac9-8674-1821b24f1608','91fed0c7-25ea-53b7-8e53-6ec34cb6a87b','Rantai makanan di kebun','ipas-kelas-6',6,'C','Bab 1','dasar','draft',5,'{"summary":"Mengenali hubungan makhluk hidup dalam ekosistem.","video_url":null,"blocks":[{"type":"text","body":"Rumput menggunakan energi matahari untuk membuat makanan. Belalang memakan rumput. Katak memakan belalang. Hubungan ini membentuk rantai makanan: rumput → belalang → katak. Setiap makhluk hidup berperan dalam ekosistem."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Amati lingkungan tanpa merusak tumbuhan atau mengganggu hewan. Mintalah pendampingan orang dewasa."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('26b585c6-932c-5504-aaf2-7b632fda1c99','0eddb8a4-03db-5dfb-b42b-e2a13edcb6a8','Tanggung jawab dan keputusan bersama','pancasila-kelas-6',6,'C','Bab 1','dasar','draft',5,'{"summary":"Berlatih menghargai perbedaan, mendengar, dan bertanggung jawab.","video_url":null,"blocks":[{"type":"text","body":"Kelas Nara ingin merawat taman. Setiap anak boleh menyampaikan pendapat. Mereka mendengarkan tanpa mengejek, lalu bermusyawarah. Tugas dibagi dengan adil. Saat ada teman kesulitan, teman lain membantu. Semua menjaga keputusan bersama."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Berbeda pendapat itu wajar. Dengarkan alasan teman dan bicaralah dengan sopan."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('4c451b4e-0fa6-5445-aac6-f82d7f1f5a57','620ca8d1-025d-5ecc-80e1-727f5c59216d','Describing our little garden','bahasa-inggris-kelas-6',6,'C','Bab 1','dasar','draft',5,'{"summary":"Mengenal kosakata bahasa Inggris melalui kalimat sederhana.","video_url":null,"blocks":[{"type":"text","body":"Hello! My name is Nara. I have a little garden. The leaves are green. There are three flowers. I water the plants every morning. Thank you for helping me!"},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Baca perlahan. Cocokkan kata dengan benda atau kegiatan di sekitarmu."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values ('3c08e360-bcde-51fe-904e-d13fee850b02','02046bef-ad4b-5a7f-9be9-1f198d03f6d8','Berkarya dari bahan sekitar','seni-budaya-kelas-6',6,'C','Bab 1','dasar','draft',5,'{"summary":"Mengenal warna dan kolase sambil berani mengekspresikan ide.","video_url":null,"blocks":[{"type":"text","body":"Nara membuat kolase taman dari potongan kertas. Ia menggabungkan merah dan kuning untuk mendapatkan jingga pada cat. Bentuk disusun sebelum direkatkan. Nara menggunakan bahan dengan hemat dan merapikan meja setelah berkarya. Setiap karya boleh berbeda."},{"type":"image","url":"/assets/kebun-belajar.svg","caption":"Kebun Nara: tempat mengamati, bercerita, dan belajar bersama."},{"type":"tip","body":"Gunakan gunting dengan pendampingan orang dewasa. Hargai karyamu dan karya teman."},{"type":"text","body":"Coba ceritakan kembali dengan bahasamu sendiri. Apa satu hal baru yang kamu pelajari? Setelah siap, kerjakan latihan. Tidak apa-apa jika belum benar; kita bisa mencoba lagi."}],"editorial_notice":"Materi contoh untuk menguji aplikasi. Belum ditinjau guru atau dipetakan sebagai kurikulum resmi."}'::jsonb) on conflict (id) do nothing;
