insert into public.questions(id,lesson_id,prompt,options,difficulty,status) values ('f194ad45-cbe6-5592-afb2-1040e1b6e0fb','e82a5e37-3b19-5ec0-8aca-e148b6c830ee','Apa arti “green”?','["Merah","Hijau","Biru","Kuning"]'::jsonb,'dasar','draft') on conflict (id) do nothing;
