insert into public.questions(id,lesson_id,prompt,options,difficulty,status) values ('b539ba2e-52ea-507a-ab5a-f68ab9988b99','e82a5e37-3b19-5ec0-8aca-e148b6c830ee','Berapa arti “three flowers”?','["Dua bunga","Empat bunga","Tiga bunga","Lima bunga"]'::jsonb,'dasar','draft') on conflict (id) do nothing;
